/**
 * Retry policy for the checkout API.
 *
 * Every request the cart makes to the checkout service goes through
 * `retryFetch`. A 5xx is tried again with exponential backoff, up to
 * `init.retries` more times; anything under 500 — success, a 4xx, a
 * redirect — goes straight back to the caller, because retrying a bad
 * request cannot make it a good one.
 *
 * Idempotency is the caller's promise, not this module's: a PUT that is
 * retried lands twice if the first attempt got through and only the
 * response was lost. The cart PUT is keyed by cart id, so that is safe.
 */

export interface RetryInit extends RequestInit {
  /** How many times to try again after the first attempt. 0 means never. */
  retries: number
}

/** Thrown once the last retry has also come back 5xx. */
export class RetryExhausted extends Error {
  constructor(retries: number) {
    super(`gave up after ${retries} retries`)
    this.name = 'RetryExhausted'
  }
}

/**
 * 250ms, 500ms, 1s, 2s — doubling per attempt, so three retries cost
 * about two seconds end to end. No jitter yet: the only caller today is
 * one browser tab, and a thundering herd is not a concern this module
 * has to answer.
 */
const backoff = (attempt: number) =>
  new Promise((resolve) => setTimeout(resolve, 2 ** attempt * 250))

export async function retryFetch(input: RequestInfo, init: RetryInit) {
  // A body stream survives exactly one send; buffer it once and re-arm per attempt.
  const body = init.body ? await bufferBody(init.body) : undefined
  for (let attempt = 0; attempt <= init.retries; attempt += 1) {
    const response = await fetch(input, body ? { ...init, body: body.rearm() } : init)
    if (response.status < 500) return response
    if (attempt < init.retries) await backoff(attempt)
  }
  throw new RetryExhausted(init.retries)
}

async function bufferBody(body: BodyInit): Promise<{ rearm(): BodyInit }> {
  const bytes = await new Response(body).arrayBuffer()
  return { rearm: () => bytes.slice(0) }
}

