import { afterEach, describe, expect, it, vi } from 'vitest'

import { RetryExhausted, retryFetch } from './retry'

const CART = JSON.stringify({ id: 'cart-7', items: [{ sku: 'A1' }, { sku: 'B2' }, { sku: 'C3' }] })

/** A fetch that answers 502 `failures` times, then 200 with whatever it was sent. */
const flaky = (failures: number) => {
  const bodies: string[] = []
  const fetch = vi.fn(async (_input: RequestInfo, init?: RequestInit) => {
    bodies.push(init?.body ? await new Response(init.body).text() : '')
    if (fetch.mock.calls.length <= failures) return new Response('bad gateway', { status: 502 })
    return new Response(bodies[bodies.length - 1], { status: 200 })
  })
  return { fetch, bodies }
}

describe('retryFetch', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
    vi.useRealTimers()
  })

  it('retries an idempotent GET on 502', async () => {
    const { fetch } = flaky(1)
    vi.stubGlobal('fetch', fetch)
    vi.useFakeTimers()
    const pending = retryFetch('/api/checkout/cart-7', { method: 'GET', retries: 3 })
    await vi.runAllTimersAsync()
    expect((await pending).status).toBe(200)
    expect(fetch).toHaveBeenCalledTimes(2)
  })

  it('gives up after three attempts', async () => {
    const { fetch } = flaky(Infinity)
    vi.stubGlobal('fetch', fetch)
    vi.useFakeTimers()
    const settled = retryFetch('/api/checkout/cart-7', { method: 'GET', retries: 2 }).catch((error) => error)
    await vi.runAllTimersAsync()
    expect(await settled).toBeInstanceOf(RetryExhausted)
    expect(fetch).toHaveBeenCalledTimes(3)
  })

  it('preserves the cart body across retries', async () => {
    const { fetch, bodies } = flaky(1)
    vi.stubGlobal('fetch', fetch)
    vi.useFakeTimers()
    // A stream is spent by its first send. The second attempt must carry the cart again.
    const pending = retryFetch('/api/checkout/cart-7', { method: 'PUT', body: new Blob([CART]).stream(), retries: 3 })
    await vi.runAllTimersAsync()
    expect(JSON.parse(await (await pending).text()).items).toHaveLength(3)
    expect(bodies[1], 'expected a cart of 3 items, request body was empty').toBe(CART)
  })
})

